/**
 * Server-side bundle loader.
 *
 * The bundle is generated by `npm run evidence:build` into `public/evidence/`.
 * The page loads it once per request and passes it to the client provider. A
 * missing bundle is not fatal: the app still renders, and the Evidence tab says
 * the dataset is unverified.
 */

import { readFile } from "node:fs/promises";
import path from "node:path";
import type { EvidenceBundle } from "./schema";

const cache = new Map<string, EvidenceBundle | null>();

export async function loadEvidenceBundle(regionId: string): Promise<EvidenceBundle | null> {
  if (cache.has(regionId)) return cache.get(regionId) ?? null;
  const file = path.join(process.cwd(), "public", "evidence", `${regionId}.json`);
  try {
    const text = await readFile(file, "utf8");
    const bundle = JSON.parse(text) as EvidenceBundle;
    cache.set(regionId, bundle);
    return bundle;
  } catch {
    cache.set(regionId, null);
    return null;
  }
}
